// Extract Due Diligence tasks from Kanboard
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks from Kanboard`);

const dueDiligenceTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const description = task.description ? task.description.toString().trim() : '';

  // Check if title contains "Due Diligence" (case insensitive)
  const titleLower = title.toLowerCase();
  if (titleLower.includes('due diligence')) {
    let companyName = '';

    // Extract company name from title
    const colonPattern = /due diligence:\s*(.+)/i;
    const colonMatch = title.match(colonPattern);
    if (colonMatch) {
      companyName = colonMatch[1].trim().replace(/^["']+|["']+$/g, '');
    } else {
      const afterDD = title.substring(title.toLowerCase().indexOf('due diligence') + 13).trim();
      companyName = afterDD.replace(/^[:\s"']+/, '').replace(/["']+$/, '').trim() || 'Unknown Company';
    }

    // Extract website from description
    const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
    const urls = description.match(urlRegex) || [];
    const website = urls.length > 0 ? urls[0] : '';

    console.log(`✅ Found Due Diligence task: "${companyName}" (ID: ${task.id})`);

    dueDiligenceTasks.push({
      json: {
        kanboard_task_id: task.id,
        title: title,
        company_name: companyName,
        website: website,
        description: description,
        project_id: task.project_id || 1,
        status: 'pending',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      }
    });
  }
}

if (dueDiligenceTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found');
  return [{ json: { message: 'No Due Diligence tasks found', skip: true } }];
}

console.log(`📋 Processing ${dueDiligenceTasks.length} Due Diligence tasks`);
return dueDiligenceTasks;

// Process attachments and prepare for file extraction
const taskData = $('Extract DD Tasks').first().json;
const attachmentResponse = $input.first().json;
const attachments = attachmentResponse.result || [];

console.log(`Found ${attachments.length} attachments for task ${taskData.kanboard_task_id}`);

if (attachments.length === 0) {
  return [{
    json: {
      ...taskData,
      attachments: [],
      attachment_info: 'No attachments found',
      hasAttachments: false
    }
  }];
}

// Process each attachment
const processedAttachments = [];
for (const attachment of attachments) {
  if (attachment.name && (attachment.name.toLowerCase().endsWith('.pdf') || 
                         attachment.name.toLowerCase().endsWith('.doc') ||
                         attachment.name.toLowerCase().endsWith('.docx') ||
                         attachment.name.toLowerCase().endsWith('.txt'))) {
    processedAttachments.push({
      id: attachment.id,
      name: attachment.name,
      size: attachment.size,
      download_url: `http://localhost:8000/?controller=FileViewerController&action=download&file_id=${attachment.id}&project_id=${taskData.project_id}`
    });
  }
}

return [{
  json: {
    ...taskData,
    attachments: processedAttachments,
    attachment_info: processedAttachments.map(a => `${a.name} (${a.size} bytes)`).join(', '),
    hasAttachments: processedAttachments.length > 0
  }
}];

// Check which sections are missing for each report
const reports = $input.all();
const sectionsToGenerate = [];

// Define all 20 due diligence sections
const ddSections = [
  'introduction_engagement_context',
  'methodology_reliability_levels',
  'company_overview',
  'business_model_unit_economics',
  'products_technology',
  'target_market_competitive_set',
  'financials_multi_year',
  'cash_burn_runway',
  'revenue_quality_client_cohorts',
  'partnerships_ecosystem',
  'intellectual_property',
  'legal_regulatory',
  'governance_board_effectiveness',
  'capital_structure_dilution',
  'risk_matrix_mitigations',
  'gaps_uncertainties_disclaimers',
  'scenario_analysis',
  'strategic_options',
  'recommendations_next_steps',
  'source_map_integrity_log'
];

for (const report of reports) {
  const reportJson = report.json;

  for (const section of ddSections) {
    // Check if section is null or empty
    if (!reportJson[section] || reportJson[section].trim() === '') {
      sectionsToGenerate.push({
        json: {
          id: reportJson.id,
          kanboard_task_id: reportJson.kanboard_task_id,
          company_name: reportJson.company_name,
          website: reportJson.website,
          description: reportJson.description,
          attachment_info: reportJson.attachment_info,
          section_name: section,
          section_title: section.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
          existing_sections: ddSections.filter(s => reportJson[s] && reportJson[s].trim() !== '').join(', ')
        }
      });
      break; // Generate one section at a time per report
    }
  }
}

console.log(`📊 Found ${sectionsToGenerate.length} sections to generate`);

if (sectionsToGenerate.length === 0) {
  return [{ json: { message: 'All reports complete', skip: true } }];
}

return sectionsToGenerate;

// Generate AI prompt for the specific DD section
const sectionData = $input.first().json;

const prompt = `You are an expert financial analyst conducting comprehensive due diligence on ${sectionData.company_name}.

COMPANY INFORMATION:
- Name: ${sectionData.company_name}
- Website: ${sectionData.website || 'Not provided'}
- Description: ${sectionData.description || 'Not provided'}
- Attachments: ${sectionData.attachment_info || 'No attachments'}

PREVIOUSLY COMPLETED SECTIONS:
${sectionData.existing_sections || 'None yet'}

TASK: Generate the "${sectionData.section_title}" section for this due diligence report.

SECTION-SPECIFIC REQUIREMENTS:

${getSectionRequirements(sectionData.section_name)}

GENERAL REQUIREMENTS:
- Be specific and factual
- Use professional financial analysis language
- Minimum 400 words
- Include key metrics, risks, and insights
- Reference the company's actual business model and industry
- Provide actionable analysis

Generate ONLY the content for the "${sectionData.section_title}" section:`;

function getSectionRequirements(sectionName) {
  const requirements = {
    'introduction_engagement_context': 'Provide context for the engagement, scope of work, limitations, and executive summary of key findings.',
    'methodology_reliability_levels': 'Detail the methodology used, data sources, reliability levels of information, and confidence ratings.',
    'company_overview': 'Comprehensive overview including history, mission, business model, key personnel, and corporate structure.',
    'business_model_unit_economics': 'Analyze revenue streams, cost structure, unit economics, scalability, and business model sustainability.',
    'products_technology': 'Detailed analysis of products/services, technology stack, IP, competitive advantages, and development roadmap.',
    'target_market_competitive_set': 'Market size, growth, competitive landscape, positioning, and market share analysis.',
    'financials_multi_year': 'Multi-year financial analysis including P&L, balance sheet, cash flow, and key financial ratios.',
    'cash_burn_runway': 'Current cash position, burn rate analysis, runway calculations, and funding requirements.',
    'revenue_quality_client_cohorts': 'Revenue quality assessment, client concentration, retention rates, and cohort analysis.',
    'partnerships_ecosystem': 'Strategic partnerships, supplier relationships, distribution channels, and ecosystem analysis.',
    'intellectual_property': 'IP portfolio, patents, trademarks, trade secrets, and IP protection strategy.',
    'legal_regulatory': 'Legal structure, compliance status, regulatory risks, litigation, and legal considerations.',
    'governance_board_effectiveness': 'Corporate governance, board composition, management quality, and organizational effectiveness.',
    'capital_structure_dilution': 'Current cap table, ownership structure, dilution analysis, and liquidation preferences.',
    'risk_matrix_mitigations': 'Comprehensive risk assessment with mitigation strategies and risk ratings.',
    'gaps_uncertainties_disclaimers': 'Information gaps, areas of uncertainty, limitations of analysis, and important disclaimers.',
    'scenario_analysis': 'Base, optimistic, and pessimistic scenarios with probability assessments and key assumptions.',
    'strategic_options': 'Strategic alternatives, growth options, exit strategies, and strategic recommendations.',
    'recommendations_next_steps': 'Clear recommendations, action items, next steps, and decision framework.',
    'source_map_integrity_log': 'Complete source documentation, data integrity checks, and verification methods used.'
  };
  return requirements[sectionName] || 'Provide comprehensive analysis relevant to this section.';
}

console.log(`🤖 Generating prompt for ${sectionData.section_title} section`);

return [{
  json: {
    ...sectionData,
    ai_prompt: prompt
  }
}];

// Process AI response and prepare for database update
const sectionData = $('Create Section Prompt').first().json;
const aiResponse = $input.first().json;

const generatedContent = aiResponse.response || '';
const cleanContent = generatedContent.trim();

console.log(`📝 Generated ${sectionData.section_title}: ${cleanContent.substring(0, 100)}...`);

return [{
  json: {
    id: sectionData.id,
    section_name: sectionData.section_name,
    section_content: cleanContent,
    updated_at: new Date().toISOString()
  }
}];

// Check if reports are complete (all 20 sections filled)
const reports = $input.all();
const completeReports = [];

const ddSections = [
  'introduction_engagement_context', 'methodology_reliability_levels', 'company_overview',
  'business_model_unit_economics', 'products_technology', 'target_market_competitive_set',
  'financials_multi_year', 'cash_burn_runway', 'revenue_quality_client_cohorts',
  'partnerships_ecosystem', 'intellectual_property', 'legal_regulatory',
  'governance_board_effectiveness', 'capital_structure_dilution', 'risk_matrix_mitigations',
  'gaps_uncertainties_disclaimers', 'scenario_analysis', 'strategic_options',
  'recommendations_next_steps', 'source_map_integrity_log'
];

for (const report of reports) {
  const reportJson = report.json;

  // Check if all sections are completed
  const completedSections = ddSections.filter(section => 
    reportJson[section] && reportJson[section].trim() !== ''
  );

  if (completedSections.length === ddSections.length) {
    console.log(`✅ Report complete for ${reportJson.company_name}`);
    completeReports.push({
      json: {
        ...reportJson,
        isComplete: true
      }
    });
  }
}

if (completeReports.length === 0) {
  return [{ json: { message: 'No complete reports found', skip: true } }];
}

return completeReports;

